/**
 * emit to subscription queries of type FindLineageNode,
 * but only if the id matches
 *
 * @param		entity	LineageNode
 */
	protected void emitFindLineageNode( LineageNode entity ) {
		LOGGER.info("handling emitFindLineageNode" );
		
	    queryUpdateEmitter.emit(FindLineageNodeQuery.class,
	                            query -> query.getFilter().getLineageNodeId().equals(entity.getLineageNodeId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllLineageNode
	 * 
	 * @param		entity	LineageNode
	 */
	protected void emitFindAllLineageNode( LineageNode entity ) {
		LOGGER.info("handling emitFindAllLineageNode" );
		
	    queryUpdateEmitter.emit(FindAllLineageNodeQuery.class,
	                            query -> true,
	                            entity);
	}

